from itertools import product

# demo1 Ts: (bbox rows, cols, type) type: 'up' = stem above bar (┴), 'down' = stem below (┬)
d1 = [
 ((1,2),(2,4),'up'),   # T1
 ((4,5),(7,9),'down'), # T2
 ((5,6),(0,2),'down'), # T3
 ((8,9),(5,7),'down'), # T4
 ((9,10),(1,3),'up'),  # T5
 ((9,10),(12,14),'up'),# T6
 ((12,13),(6,8),'down'),# T7
]
d1_out = {(0,0):3,(0,2):3,(0,3):1,(0,5):1,(2,0):3,(2,3):1,(2,5):1}

d2 = [((0,1),(0,2),'down'), ((3,4),(0,2),'up')]
d2_out = {(0,0):3,(0,3):1}

def anchors(r0,r1,c0,c1):
    return {
      'tl':(r0,c0), 'tr':(r0,c1), 'bl':(r1,c0), 'br':(r1,c1),
      'tc':(r0,(c0+c1)/2), 'bc':(r1,(c0+c1)/2),
      'lc':((r0+r1)/2,c0), 'rc':((r0+r1)/2,c1),
      'c':((r0+r1)/2,(c0+c1)/2),
      'stem_or_bar_top': None, 'stem_or_bar_bot': None,
    }
# explicit stem/bar coords
def sb(r0,r1,c0,c1,t):
    if t=='up':   # stem above: stem row r0, bar row r1
        return {'stem':(r0,(c0+c1)/2),'bar':(r1,(c0+c1)/2)}
    else:         # stem below: bar row r0, stem row r1
        return {'stem':(r1,(c0+c1)/2),'bar':(r0,(c0+c1)/2)}

def fe(x,s,mode):
    v=x/s
    return int(v//1) if mode=='f' else (int(-(-v//1)) if mode=='c' else round(v))

results=[]
H1,W1=15,15; H2,W2=5,4
outH,outW=3,6
for arn in ['tl','tr','bl','br','tc','bc','lc','rc','c','stem','bar','stem_or_bar_top']:
  for rf,cf in product('fc',repeat=2):
    ok=True
    for demo,(H,W),out in ((1,(15,15),d1_out),(2,(5,4),d2_out)):
        for (r0,r1),(c0,c1),t in (d1 if demo==1 else d2):
            if arn in ('stem','bar'):
                a=sb(r0,r1,c0,c1,t)[arn]
            elif arn=='stem_or_bar_top':
                a=(r0,(c0+c1)/2)
            else:
                a=anchors(r0,r1,c0,c1)[arn]
            rs = H/outH; cs = W/outW
            # fixed canvas: scale by input dims
            r_,c_ = fe(a[0],rs,rf), fe(a[1],cs,cf)
            if (r_,c_) not in out or out[(r_,c_)] != (3 if t=='up' else 1):
                ok=False; break
        if not ok: break
    if ok: results.append((arn,rf,cf))
print(results[:20], len(results))

